def nb_chunks(nb_workers, length):
    """Return the number of chunks to split a sequence of ``length`` items into.

    Never returns more chunks than there are workers or items, and never
    returns less than one chunk.
    """
    return max(1, min(nb_workers, length))


def chunk_list(seq, nb):
    """Split the sequence ``seq`` into ``nb`` chunks of nearly equal size."""
    nb = nb_chunks(nb, len(seq))
