    If ``func`` returns a scalar per column, each partial result is a Series
    indexed by the chunk columns: they are stacked along rows. If ``func``
    returns a Series per column, each partial result is a DataFrame whose
    columns are the chunk columns: they are stacked along columns.
    """
    if len(results) == 1:
        return results[0]
    if isinstance(results[0], pd.DataFrame):
        return pd.concat(results, axis=1)
    return pd.concat(results, axis=0)

