import dill
import pandas as pd

from pandarallel.data_types.dataframe_groupby import plan_groups
from pandarallel.data_types.generic import reduce_concat_rows


def _window_kwargs(expander):
    return {
        "min_periods": expander.min_periods,
        "center": expander.center,
        "axis": expander.axis,
        "method": expander.method,
    }


def work(data, extra):
    subset, by = data
    func = dill.loads(extra["func"])
    args = dill.loads(extra["args"])
    kwargs = dill.loads(extra["kwargs"])

    _, spec = by  # Expanding groupby always re-groups with arrays.
    groupers = [pd.Series(values, name=name) for name, values in spec]
    by_arg = groupers if len(groupers) > 1 else groupers[0]

    expander = subset.groupby(by_arg).expanding(**extra["window_kwargs"])
    return expander.apply(func, *args, **kwargs)


def parallel_apply(self, func, *args, **kwargs):
    """Parallel version of ``ExpandingGroupby.apply``."""
    from pandarallel.core import pandarallel, run_workers

    config = pandarallel.config()
    datas, _ = plan_groups(self, config.nb_workers)
    extra = {
        "func": dill.dumps(func),
        "args": dill.dumps(args),
        "kwargs": dill.dumps(kwargs),
        "window_kwargs": _window_kwargs(self),
    }
    return run_workers(
        config, work, datas, extra, reduce_concat_rows, "parallel_apply"
    )

